import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph: A Journey to 1 TiB/s | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Ceph: A Journey to 1 TiB/s | Ceph Days NYC 2024","date":"2024-05-16T00:00:00.000Z","updated":"None","tags":["Ceph性能优化","分布式存储","高速存储集群","NVMe存储","Ceph Days NYC 2024"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.md"};function r(s,a,_,n,h,u){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p><strong>实现每秒一万亿字节的存储性能之旅</strong></p><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>2024年某月某日</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>Seth以及其他相关技术人员和客户代表</p><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>项目背景与客户需求</strong>：</p><ul><li>客户针对高速存储需求提出挑战性案例，并初步设计了架构，寻求专业建议。</li><li>客户指定使用Dell品牌硬件，每个机架最多部署四个节点，共七个机架，以确保故障域隔离。</li><li>客户希望从HDD集群迁移到NVMe集群，且要求在迁移过程中实现零停机时间。</li></ul></li><li><p><strong>硬件与网络配置</strong>：</p><ul><li>客户具备高速网络基础设施，具体细节未透露，但参考了Bloomberg的网络配置。</li><li>硬件设计采用100 GigE网络，测试环境使用的是focal auntu系统。</li></ul></li><li><p><strong>性能优化与挑战</strong>：</p><ul><li>通过Numa调优、BIOS设置和使用单处理器节点提高了性能。</li><li>发现并解决了多个性能瓶颈，包括C States和IMU的禁用，以及Upstream davan auntu构建问题。</li><li>通过单个OSD和节点的测试，逐步排查并解决了性能下降的问题。</li></ul></li><li><p><strong>测试与结果</strong>：</p><ul><li>在优化设置后，集群性能显著提升，特别是在320个OSD的配置下实现了线性扩展。</li><li>最终在3x复制模式下实现了每秒一万亿字节的读取性能，写入性能虽稍逊，但仍达到预期目标。</li><li>使用Erasure编码时，读取性能受到网络影响较大，但写入性能有所提升。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>客户将继续优化其应用以充分利用新集群的性能。</li><li>社区合作将继续推进，目标是超越现有行业标准，如Vast和DDN W。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了硬件配置和网络设置的最佳实践。</li><li>确定了性能优化的关键步骤和解决方案。</li><li>客户集群成功迁移并开始运行在新的NVMe集群上。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控和优化集群性能。</li><li>探索进一步的性能提升方法，如改进TCP堆栈。</li><li>加强社区合作，共同推动存储技术的进步。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术和配置细节，如C States、IMU、Erasure编码等，是优化性能的关键技术点，需在后续工作中重点关注和应用。</li></ul>',15)])])}const c=e(o,[["render",r]]);export{d as __pageData,c as default};
